using UnityEngine;
using Verse;

namespace RiMCP.UI
{
    // The Nyx icon (generated by scripts/make-nyx-icon.py). Loaded lazily on first draw, which
    // always happens on the main thread (GUI code).
    public static class ChatIcon
    {
        private static Texture2D texture;

        public static Texture2D Texture
        {
            get
            {
                if (texture == null)
                {
                    texture = ContentFinder<Texture2D>.Get("UI/RiMCP/Nyx", false);
                }
                return texture;
            }
        }

        public static void Draw(Rect rect)
        {
            Texture2D icon = Texture;
            if (icon != null)
            {
                GUI.DrawTexture(rect, icon);
            }
        }
    }
}
